import mongoose, { Schema, Document } from 'mongoose';
import { CHANNELS } from './notification.model';

// Digits plus common separators: (412) 555-0100, +1 412.555.0100
export const PHONE_PATTERN = /^[0-9()+\-.\s]{7,20}$/;
export const EMAIL_PATTERN = /^\S+@\S+\.\S+$/;

export interface IInstructor extends Document {
  instructorId: string;
  firstName: string;
  lastName: string;
  address: string;
  phone: string;
  email: string;
  preferredContact: (typeof CHANNELS)[number];
  createdAt: Date;
}

/** A studio instructor. The readable instructorId (I00001) is generated by the service, not sent by the client. */
const instructorSchema = new Schema<IInstructor>(
  {
    instructorId: {
      type: String,
      required: true,
    },
    firstName: {
      type: String,
      required: [true, 'First name is required'],
      trim: true,
    },
    lastName: {
      type: String,
      required: [true, 'Last name is required'],
      trim: true,
    },
    address: {
      type: String,
      required: [true, 'Address is required'],
      trim: true,
    },
    phone: {
      type: String,
      required: [true, 'Phone is required'],
      trim: true,
      match: [PHONE_PATTERN, 'Phone is not valid'],
    },
    email: {
      type: String,
      required: [true, 'Email is required'],
      trim: true,
      lowercase: true,
      match: [EMAIL_PATTERN, 'Email is not valid'],
    },
    preferredContact: {
      type: String,
      enum: CHANNELS,
      required: [true, 'Preferred contact is required'],
    },
  },
  {
    timestamps: true,
  }
);

// No two instructors share an ID
instructorSchema.index({ instructorId: 1 }, { unique: true });

export const Instructor = mongoose.model<IInstructor>('Instructor', instructorSchema);
